import json
from pathlib import Path
from tools.k_rule_inventory import inventory_verification

inventory = inventory_verification(Path("/reference/k-proof"))
manifest = json.loads(Path("/reference/lemma-discovery.json").read_text())
manifest_class = {
    entry["source_rule_id"]: entry["classification"]
    for entry in manifest["rules"]
}

independent = []
for rule in inventory["rules"]:
    line = rule["start_line"]
    if line in (7, 10):
        classification = "DOMAIN_LEMMA"
        rationale = (
            "An unproved Map-hook algebra fact used by fresh-key update or "
            "function-frame deletion; it defines no named symbol and is not "
            "an ordinary <k>-cell execution rule."
        )
    elif 18 <= line <= 190:
        classification = "OPERATIONAL_RULE"
        rationale = (
            "A configuration or <k>-cell execution/observation step: local "
            "lookup, assignment/binding, strictness-normalized comparison/"
            "control/call dispatch, or structural iterator execution."
        )
    elif 195 <= line <= 248:
        classification = "DEFINITION"
        rationale = (
            "A guarded base/recursive equation defining a named mathematical "
            "summary: trialPrime, trialDivisor, isPrime, largestPrime, "
            "digitAcc, or digitSum."
        )
    elif 252 <= line <= 302:
        classification = "DEFINITION"
        rationale = (
            "A macro equation defining a named AST fragment from the exact "
            "translated source function."
        )
    elif line == 307:
        classification = "OPERATIONAL_RULE"
        rationale = (
            "A composed but bounded operational entry-prefix rewrite over "
            "<k>, environment, scope allocation, and stack; it executes/"
            "observes program state and is neither a definition nor a proved "
            "derived theorem."
        )
    elif line == 342:
        classification = "DEFINITION"
        rationale = (
            "A macro equation defining the named solutionModule proof term "
            "from the target function closure."
        )
    else:
        raise AssertionError(f"unclassified source line {line}")
    independent.append({
        "source_rule_id": rule["source_rule_id"],
        "span": [rule["start_line"], rule["end_line"]],
        "attributes": rule["attributes"],
        "classification": classification,
        "rationale": rationale,
        "matches_protected_manifest": (
            classification == manifest_class[rule["source_rule_id"]]
        ),
        "simplification_policy_ok": (
            "simplification" not in rule["attributes"]
            or classification in {"DEFINITION", "DOMAIN_LEMMA"}
        ),
    })

domain_ids = [
    entry["source_rule_id"]
    for entry in independent
    if entry["classification"] == "DOMAIN_LEMMA"
]
print(json.dumps({
    "inventory_sha256": inventory["inventory_sha256"],
    "entries": independent,
    "all_45_reclassified": len(independent) == 45,
    "all_match_protected_manifest": all(
        entry["matches_protected_manifest"] for entry in independent
    ),
    "all_simplification_rules_allowed": all(
        entry["simplification_policy_ok"] for entry in independent
    ),
    "counts": {
        role: sum(
            entry["classification"] == role for entry in independent
        )
        for role in (
            "DEFINITION",
            "OPERATIONAL_RULE",
            "PROVED_DERIVED_LEMMA",
            "DOMAIN_LEMMA",
        )
    },
    "domain_ids": domain_ids,
    "domain_relevance": {
        domain_ids[0]: (
