            "functions.k:85-90 after the candidate function returns."
        ),
        domain_ids[1]: (
            "Directly supports fresh function-frame allocation, parameter/"
            "local binding, assignment, and loop-target updates used by this "
            "source program."
        ),
    },
}, indent=2, sort_keys=True))
